\label{nc dyn sys} 
Let $(E,\Vert{}\cdot\Vert{})$ be a real ordered Banach space, and let $G$ be a locally compact second countable (l.c.s.c.) group. A \emph{noncommutative dynamical system} is a triple $(E,G,\gamma)$, where $\gamma : G \to \mathcal{B}(E)$ is a mapping satisfying $\gamma_s \circ \gamma_t = \gamma_{st}$ for all $s,t \in G$, and the following conditions hold:
\begin{enumerate}
    \item For every $a \in E$, the orbit map $s \mapsto \gamma_s(a)$ is continuous on $G$, where $E$ is equipped with the norm topology (and the $w^*$-topology in the case where $E=\mathcal{M}$).
    \item The operators are uniformly bounded, i.e., $\displaystyle\sup_{s \in G}\|\gamma_s\| < \infty$.
    \item Positivity is preserved: if $a \ge 0$, then $\gamma_s(a) \ge 0$ for all $s\in G$.
\end{enumerate}

\label{Reiter-defn}
A sequence $ (h_n)$    in $L^1(G, m)$ such that $$ h_n \geq 0, ~~ \int_G h_n d m = 1, ~ \text{ for all } n \in \mathbb N$$ is called a \emph{ left (resp. right) Reiter sequence } if 
$$ \lim_{ n \to \infty } \left\Vert \lambda_g(h_n)- h_n\right\Vert_1= 0, (\textit{resp.} \lim_{ n \to \infty } \left\Vert \rho_g(h_n)- h_n\right\Vert_1= 0)\text{ for all } g \in G,$$
where $ \lambda_g(h)(s) = h(g^{-1} s)$ and $\rho_g(h)(s) = h( sg)$ , for $ g, s \in G$ and $ h \in L^1(G, m)$. Equivalently, for any compact subset $K$ of $G$
\begin{align*}
    \lim_{n \to \infty} \sup_{g \in K}\left\Vert \lambda_g(h_n)- h_n\right\Vert_1= 0, ~~(\textit{resp.}\lim_{n \to \infty} \sup_{g \in K}\left\Vert \rho_g(h_n)- h_n\right\Vert_1= 0).
\end{align*}
The argument is similar to the F\o lner sequence case \cite{Paterson1988}.

\label{finite-sum-aprox}
 Let $G$ be a locally compact group with a right Haar measure $m$.  Suppose $(h_n)$ be a right Reiter sequence, and $(\varepsilon_n)\subseteq (0, 1)$ is a sequence of positive reals with $ \displaystyle\lim_{n \to \infty} \varepsilon_n = 0$; then there exists a right Reiter sequence $(s_n)$ consisting of simple functions such that 
 $$ \left\Vert h_n-s_n\right\Vert_{ L^1(G, m )} \leq \varepsilon_n, \text{ for all } n \in \mathbb N. $$

\label{prop: int over good set}
	Let $K_0$ be a compact subset of $G$ containing $e$ and $U$ be a compact neighbourhood of $e$. Write $K=UK_0$. Then for any set measurable set $F \subseteq G$ with $ 0 <m(F) < \infty  $, define
	\begin{align*}
		\Phi :=\int_K  \frac{m(Fg\Delta F)}{m(F)}\,dm(g).
	\end{align*}
	If $\Phi\leq \varepsilon$ and $\varepsilon>0$, then 
	\begin{align*}
		\sup_{x\in K_0} \frac{m(Fx\Delta F)}{m(F)}\leq \frac{2 \varepsilon}{m(U)}.
	\end{align*}

Fix $x\in K_0$. Then for every $g\in G$, we know
	\begin{align*}
		m(Fx\Delta F) \leq m(Fx\Delta Fg) + m(Fg\Delta F).
	\end{align*}
	Then integrating over $ Ux$, since $m(Ux)=m(U)$, we have
	\begin{align*}
		m(U)m(Fx\Delta F) \leq \int_{Ux} m(Fx\Delta Fg)\,dm(g) + \int_{Ux} m(Fg\Delta F)\,dm(g).
	\end{align*}
	To estimate the first integral, using the right invariance of Haar measure, we obtain
	\begin{align*}
		\int_{Ux} m(Fx\Delta Fg)\,dm(g) = \int_U m(F\Delta Fu)\,dm(u) \leq \int_{K} m(F\Delta Fg)\,dm(g).
	\end{align*}
	Here, we used $U\subseteq K$. For the second integral, since $Ux\subseteq K ,$ we have
	\begin{align*}
		\int_{Ux}m(Fg\Delta F)\,dm(g) \leq \int_{K}m(Fg\Delta F)\,dm(g).
	\end{align*}
	Now, combining the above inequalities, we obtain
	\[
	m(U)m(Fx\Delta F) \leq 2 \int_{K} m(Fg\Delta F)\,dm(g).
	\]
	Which implies
	\[
	\frac{m(Fx\Delta F)}{m(F)} \leq \frac{2}{m(U)} \int_{K} \frac{m(Fg\Delta F)}{m(F)} \,dm(g).
	\]
	The last integral is $\Phi$, so we have $\frac{m(Fx\Delta F)}{m(F)} \leq \frac{2\varepsilon}{m(U)}.$ Since $x\in K_0$ was arbitrary, we have 
	\begin{align*}
		\sup_{x\in K_0} \frac{m(Fx\Delta F)}{m(F)}\leq \frac{2 \varepsilon}{m(U)}.
	\end{align*}

\label{main-thm}
   There exists a subsequence $(h_n)$ of $(s_n)$ such that   for each $n \in \mathbb N$, there exists a  $k_n\in \mathbb N$,  positive real numbers $ \{ a_{n,j} > 0:   1\leq j \leq k_n \}  $,  a function $O_n$  and collections of measurable sets  $\{ F_{n, j} : 1\leq j\leq k_n \} $ satisfying the following:
 \begin{enumerate}
     \item $ \displaystyle \sum_{ j = 1}^{k_n} a_{n, j} =a_n \leq 1$ for all $n \in \mathbb N$ with $ a_n \xrightarrow{ n \rightarrow \infty } 1$ and $ \left\Vert O_n\right\Vert_{ L^1(G, m) } < \sqrt{\varepsilon_n}, ~ $ for all $ n \in \mathbb N$.

\item  $ h_n = \displaystyle \sum_{j=1}^{k_n} a_{n,j} \frac{\mathbf{1}_{F_{n,j}}}{m(F_{n,j})} + O_n.$\\

\item $ \underset{ g \in K_n }{\sup }  \frac{ m(F_{n, j}g \Delta F_{n, j}) }{m(F_{n, j})} \lesssim \sqrt{\varepsilon_n}, \text{ for all } n \in \mathbb N \text{ and } 1 \leq j\leq k_n.$

 \end{enumerate}

Let $K$ be a compact subset of the group $G$ and $E \subset G$, the $K$-\emph{boundary} of the set $E$ is defined as the following
    \begin{align*}
        \partial_K(E):= \cup_{g \in G}\{ gK : gK \cap E \neq \emptyset, \text{ and } gK \cap E^c \neq \emptyset \}.
    \end{align*}
    Now for $\varepsilon>0$, the set $E$ is said to be $(\varepsilon, K)$-\emph{boundary invariant} if 
    \begin{align*}
        \left\vert\partial_K(E)\right\vert < \varepsilon \left\vertE\right\vert.
    \end{align*}

Let $E$ be a subset of the group $G$, the \emph{lower Banach density} of the set is defined by 
    \begin{align*}
        \underline{B}(E):= \sup_{K \subseteq G} \inf_{g \in G} \frac{\left\vertgK \cap E\right\vert}{\left\vertgK\right\vert},
    \end{align*}
    where the supremum is taken over all compact subsets $K$ of the group $G$.

\label{adm_subsequence}
    Let $\mathcal{S}:=((F_n)_n, (B_n)_n, (\mathcal{P}_n)_n)$ be a $c$-admissible F\o lner sequence for some $c \in (0,1)$. Consider $\mathcal{S}':=((F_{n_k})_k, (B_{n_k})_k, (\mathcal{P}_{n_k})_k)$. Then observe that $Adm(\mathcal{S}) \subseteq Adm(\mathcal{S}')$. Therefore, for all compact set $K$ of $G$ and $g \in G$,
    \begin{align*}
        \frac{\left\vertgK \cap Adm(\mathcal{S})\right\vert}{\left\vertgK\right\vert} \leq \frac{\left\vertgK \cap Adm(\mathcal{S}')\right\vert}{\left\vertgK\right\vert}.
    \end{align*}
    Hence, it is clear that $1-c \leq \underline{B}(Adm(\mathcal{S})) \leq \underline{B}(Adm(\mathcal{S}'))$. So, $\mathcal{S}'$ is also a $c$-admissible F\o lner sequence. We conclude that a subsequence of a $c$-admissible F\o lner sequence is $c$-admissible.

\label{Adm_Folner_sequence}
    Let $(s_n)$ be a sequence of simple functions of the form $$s_n = \sum_{j=1}^{\infty} a_{n,j} \frac{\mathbf{1}_{F_{n,j}}}{m(F_{n,j})}.$$
where $(F_{n,j})$ is a F\o lner sequence for each $j$ and there exists $k_n \in \mathbb N$ such that $F_{n,j}=F_{n,k_n}$ for all $j \geq k_n.$ Then there exists a subsequence $(s_{n_t})$ such that $(F_{n_t,j})_{ t \in \mathbb N}$ is an admissible F\o lner sequence.

We will construct the subsequence using a standard diagonal argument. 
    For $j\in \{1, \cdots, k_1\}$, first consider the F\o lner sequences $(F_{n,j})_{n=1}^{\infty}$. By Theorem A of \cite{cadilhac2022noncommutative} and Remark \ref{adm_subsequence}, we can find a subsequence of indices $N_1 \subseteq \mathbb{N}$ such that $(F_{n,j})_{n \in N_1}$ is an admissible F\o lner sequence for all  $j\in \{1, \cdots, k_1\}$.
    Let $n_1$ be the least element of $N_1$ and consider
    \begin{align*}
        s_{n_1}:= \sum_{j=1}^\infty a_{n_1,j} \frac{\mathbf{1}_{F_{n_1,j}}}{m(F_{n_1,j})}.
    \end{align*}
    Next, noting that $(F_{n,j})_{n \in N_1}$ are F\o lner sequences, where $j\in \{1, \cdots, k_{n_1}\}$, we again deploy Theorem A of \cite{cadilhac2022noncommutative} and Remark \ref{adm_subsequence}, to extract admissible F\o lner subsequences $(F_{n,j})_{n \in N_2}$, where $N_2 \subseteq N_1$ and $j\in \{1, \cdots, k_{n_1}\}$. Let $n_2$ be the least element of $N_2$ and consider
    \begin{align*}
        s_{n_2}:= \sum_{j=1}^\infty a_{n_2,j} \frac{\mathbf{1}_{F_{n_2,j}}}{m(F_{n_2,j})}.
    \end{align*}
    In general, for $l \geq 2$, let $(F_{n,j})_{n \in N_{l-1}}$,  where $j\in \{1, \cdots, k_{n_{l-1}}\}$ are F\o lner sequences. Applying Theorem A of \cite{cadilhac2022noncommutative} and Remark \ref{adm_subsequence}, we get admissible F\o lner subsequences $(F_{n,j})_{n \in N_{l}}$ for $j\in \{1, \cdots, k_{n_{l-1}}\}$, where $N_l \subseteq N_{l-1}$. Let $n_l$ be the least element of $N_l$ and write
    \begin{align*}
        s_{n_l}:= \sum_{j=1}^\infty a_{n_l,j} \frac{\mathbf{1}_{F_{n_l,j}}}{m(F_{n_l,j})}.
    \end{align*}
    Observe that for every $j \in \mathbb N$, $(F_{n_l,j})_{l \in \mathbb N}$ is an admissible F\o lner sequence. This completes the proof.

\label{weak_type_(1,1)_ergodic}
    Let $x \in L^1(\mathcal{M})$ and $\lambda > 0$. Then there exists a projection $e_x \in \mathcal{M}$ such that 
    \begin{align*}
        e_x{A}_n^s(x)e_x \leq \lambda~~\text{for all }n \in \mathbb N ~~\text{and}~~\tau(1-e_x)\leq C\frac{\|x\|_1}{\lambda}.
    \end{align*}
    For $p > 1$, $ ( A_n^s)$ satisfies a strong $(p,p)$ maximal inequality, indeed, for $ x \in L^p(\mathcal{M}, \tau) $ we have 
    $$ \left\Vert\left( {A}^s (x)\right)\right\Vert_{ L^p(\mathcal{M}; \ell^\infty)} \lesssim \left\Vertx\right\Vert_p. $$

\label{thm: bau and su convergence}
    Let $(A_n^h)_n$ be as before. Assume that $1 \leq p_0< p_1 \leq \infty$. Further, assume that $(A^h_n)_n$ is a strong type $(p,p)$ for all $p_0<p<p_1$ and $x \in L^p(\mathcal{M})$. Then the following holds.
    \begin{enumerate}[label=(\roman*)]
        \item Let $p_0<p\leq 2p_0$ and $x \in L_p(\mathcal{M})$. Then $A^h_n(x)$ converges to $Px$ in b.a.u.
        \item Let $2p_0 <p < p_1$ and $x \in L_p(\mathcal{M})$. Then $A^h_n(x)$ converges to $Px$ in a.u.
    \end{enumerate}

Let us define 
    $$
    S:= span \{ x - \alpha_s(x): x \in \mathcal{M} \cap L_1(\mathcal{M}) \}.
    $$
    Choose $x \in S$ such that $x= y - \alpha_t(y)$ for some $y \in \mathcal{M} \cap L_1(\mathcal{M})$. 


















    Since $m$ is a right Haar measure and $(h_n)_n$ is a right Reiter sequence, we observe that
    \begin{align*}
        \int_G \alpha_{gt}(y) h_n(g)dm(g)
        = \int_G \alpha_g(y) \rho_{t^{-1}}(h_n)(g)  dm(g).
    \end{align*}
    Hence, 
    \begin{align*}
        A^h_n(x)
        = \int_G \alpha_g(y) \left[ h_n(g) - \rho_{t^{-1}}(h_n)(g) \right] dm(g).
    \end{align*}
    So, we obtain
    \begin{align*}
        \left\VertA^h_n(x)\right\Vert_\infty  \leq \left\Verty\right\Vert_\infty \left\Verth_n - \rho_{t^{-1}} (h_n)\right\Vert_1 \to 0 \text{ as } n \to \infty.
    \end{align*} 
    \emph{Proof of (i):} Let $x \in L_p(\mathcal{M})$. Then there exists a sequence $(x_k)$ in $S$ such that 
    \begin{align*}
        \lim_{k \to \infty} \left\Vertx- Px - x_k\right\Vert_p = 0,
    \end{align*}
    where $P$ is the projection map from $L_p(\mathcal{M})$ onto the fixed point space. Note that $A_n^h P = P A_n^h= P$. So, by strong $(p,p)$ of $(A_n^h)_n$ we get for all $k \in \mathbb N$,
    \begin{align*}
        \left\Vert(A_n^h(x) - Px - A_n^h(x_k))_n\right\Vert_{L_p(\mathcal{M}; \ell^\infty)} \lesssim \left\Vertx- Px - x_k\right\Vert_p.
    \end{align*}
    Therefore, since $L_p(\mathcal{M}; c_0)$ is closed in $L_p(\mathcal{M}; \ell_\infty)$ and $\lim_{k \to \infty} (A_n^h(x_k))_n= (A_n^h(x) - Px)_n$ in $L_p(\mathcal{M}; \ell^\infty)$, it is now enough to prove that for all $k \in \mathbb N$, $(A^h_n(x_k))_n \in L_p(\mathcal{M}; c_0)$. Again for $x \in S$, just as before we find that $x \in L_q(\mathcal{M})$ for some $p_0<q<p$ and since $(A_n^h)_n$ is a strong type $(q,q)$, we have for all $m<n$
    \begin{align*}
    	\left\Vert(A_j^h(x))_m^n\right\Vert_{L_p(\mathcal{M}; \ell^\infty)}
    	& \lesssim \sup_{m \le j \le n} \left\VertA_j^h(x)\right\Vert_\infty^{1-q/p} \left\Vert(A_j^h(x))_m^n\right\Vert^{q/p}_{L_q(\mathcal{M}; \ell^\infty)}.\\
    	& \leq \sup_{m \le j \le n} \left( \left\Verty\right\Vert_\infty \left\Verth_n - R_{t^{-1}} h_n\right\Vert_1  \right)^{1-q/p} \left\Vert(A_j^h(x))_m^n\right\Vert^{q/p}_{L_q(\mathcal{M}; \ell^\infty)}.
    \end{align*}
    Therefore, the finite sequence $(A_1^h(x), \cdots, A_n^h(x),0,0, \cdots)$ is Cauchy and hence converges to $(A_n^h(x))_n$ in $L_p(\mathcal{M}; \ell^\infty)$. Hence, $(A_n^h(x))_n \in L_p(\mathcal{M}; c_0)$.\\

     \emph{Proof of (ii):} On the other hand, by Kadison's inequality and by the strong type $(p,p)$ inequality, for all $x \in \mathcal{M}_+ \cap L_p(\mathcal{M})_+$, we obtain
     \begin{align*}
     	\left\Vert(A_n(x))_n\right\Vert_{L_p(\mathcal{M}; \ell_\infty^c)} \leq \left\Vert((A_n(x))^2)_n\right\Vert_{L_{p/2}(\mathcal{M}; \ell_\infty)} ^{1/2} \lesssim \left\Vertx\right\Vert_p.
     \end{align*}
    Hence, a similar argument as before shows that $(A^h_nx- Px)_n \in L_p(\mathcal{M}; c^c_0)$.

\label{weak_1,1}
    Let $x\in L^1(\mathcal{M},\tau)$ and $\lambda >0.$ Then there exists a projection $e_x \in \mathcal{M}$ such that 
    \begin{align*}
        \sup_n\|e_x{A}_n^{\pi,\phi,u}(x)e_x\|_\infty \leq \lambda ~\text{ and } ~\tau(1-e_x) \lesssim \frac{\|x\|_1}{\lambda}. 
    \end{align*}

\label{JdlG_decomposition}\cite{barthmann-farhangi-kuznetsova2025jacobsdeleeuwglicksbergdecomposition}
Let $G$ be a locally compact amenable group, $m$ a left Haar measure,
$ (F_i)_{i \in I}$ a left F\o lner net, $E$ a Banach space, and
$\pi$ a relatively weakly compact representation of $G$ on $E$.
Then $\pi$ is JdLG-admissible, and it follows that 
\begin{align*}
E_c :&= \{\, \xi \in E : \pi(G)\xi \text{ is relatively compact in } E \,\}  \text{ and }\\
E_{wm} :&= \left\{\, \xi \in E :
\lim_{i} \frac{1}{m(F_i)}
\int_{F_i} \bigl| \langle \pi(g)\xi, x' \rangle \bigr| \, dm(g) = 0
\text{ for all } x' \in E' \right\}.
\end{align*}

\label{vand_corput}
    Let $f: G \to \mathcal{M}$ be a bounded measurable function and $(s_n)$ be a right Reiter sequence. Then we have 
    \begin{align}\label{vand_cor_inequality}
        \bigg\|\int_G f(g)s_n(g)dm(g)\bigg\|^2 &\leq \bigg\|\int_G\int_G\bigg(\int_Gf(g)^*f(gh_1^{-1}h_2)s_n(g)dm(g)\bigg)s_k(h_1)s_k(h_2)dm(h_1)dm(h_2)\bigg\|\nonumber\\ &+ 3\|f\|_\infty^2 \int_G\|s_n -\rho_{h^{-1}}(s_n)\|_1s_k(h)dm(h) + \|f\|_\infty^2 \Bigg(\int_G\|s_n -\rho_{h^{-1}}(s_n)\|_1s_k(h)dm(h)\Bigg)^2.
    \end{align}

\label{ergodic_L2}
    Let $(\mathcal{M}, G, \alpha)$ be as above and the action $\alpha$ is ergodic (i.e. $\mathcal{M}^G=\mathbb C1$). Suppose $(h_n)_n$ is a left Reiter sequence and $m$ is a left Haar measure. Then for every $x\in L^2(\mathcal{M},\tau)$,
    $$A^h_n(x) \to \tau(x)1$$ almost uniformly (a.u.) and in $\|\cdot\|_2$.

Let $G$ be an amenable locally compact group, $\pi \colon G \to \mathcal{U}(\mathcal{H})$ a strongly continuous unitary representation, and $(\mu_n)$ a left Reiter sequence on $G$. If $\xi \in \mathcal{H}_{\mathrm{wm}}$, then
\begin{align*}
    \int_G |\langle \pi(g)\xi, \eta \rangle| \, d\mu_n(g) \longrightarrow 0 \quad \text{for all } \eta \in \mathcal{H}.
\end{align*}

\label{keylemma}
    Let $G$ be a l.c.s.c group with two-sided Reiter sequence $(s_n)_n$ and $(\mathcal{M}, \tau)$ be a finite von Neumann algebra. $\alpha: G \to Aut (\mathcal{M})$ be a trace preserving weakly mixing action. Suppose $x \in \mathcal{M}$ with $\tau(x)=0$, Then we have 
    \begin{align*}
        \int_G\int_G |\tau(x^*\alpha_{h_1^{-1}h_2}(x))|s_k(h_1)s_k(h_2)dm(h_1)dm(h_2) \longrightarrow 0.
    \end{align*}
